/* zyb-sysadmin.js - the AI Windows Server Administrator and AI Exchange Server Administrator pages (one script, two
 * pages: windows-admin.html / exchange-admin.html set <body data-role="windows|exchange">). Talks to the SIEM API
 * /api/soc/sysadmin/* (engine/sysadmin). Read-only checks only; fixes are change plans a person approves and applies. */
(function(){
  'use strict';
  var ROLE_PAGE=document.body.getAttribute('data-role')==='exchange'?'exchange':'windows', EXN=ROLE_PAGE==='exchange';
  var API='/api/soc/sysadmin', Z=window.zybDetail, esc=Z.esc, ROLE='viewer', RANK={viewer:0,analyst:1,operator:2,admin:3}, OV=null, SV=null, CK=null, CONV=null;
  var NAME=EXN?'AI Exchange Server Administrator':'AI Windows Server Administrator';
  var $=function(id){return document.getElementById(id);};
  function can(r){return RANK[ROLE]>=RANK[r];}
  function req(method,path,body){return new Promise(function(ok,bad){var x=new XMLHttpRequest();x.open(method,API+path);x.withCredentials=true;x.timeout=method==='POST'&&/ask/.test(path)?300000:method==='POST'?180000:30000;if(body)x.setRequestHeader('Content-Type','application/json');
    x.onload=function(){var j=null;try{j=JSON.parse(x.responseText);}catch(e){ /* not JSON: treated as no data */ }if(x.status>=200&&x.status<300)return ok(j);bad(new Error((j&&(j.errors&&j.errors.join('; ')||j.error))||(x.status===404?'the SIEM does not have the AI Server Administrators yet - run the update':'HTTP '+x.status)));};
    x.onerror=x.ontimeout=function(){bad(new Error('the SIEM API is not reachable'));};x.send(body?JSON.stringify(body):null);});}
  function toast(t,err){var d=document.createElement('div');d.className='toast'+(err?' err':'');d.setAttribute('role','status');d.textContent=t;document.body.appendChild(d);setTimeout(function(){d.remove();},4500);}
  function sev(s){return '<span class="sev '+esc(s)+'">'+esc(s)+'</span>';}
  function ago(t){if(!t)return '–';var s=Math.round((Date.now()-(typeof t==='number'?t:Date.parse(t)))/1000);return s<60?s+' s ago':s<3600?Math.round(s/60)+' min ago':s<172800?Math.round(s/3600)+' h ago':Math.round(s/86400)+' d ago';}
  function tile(l,v,s,c){return '<div class="t '+(c||'')+'"><div class="l">'+esc(l)+'</div><div class="v">'+esc(String(v))+'</div><div class="s">'+esc(s||'')+'</div></div>';}
  var q='?role='+ROLE_PAGE;
  /* site filter (e.g. UAT): the server tables and the problem list show one site; the KPI tiles stay estate-wide */
  var SITE='';try{SITE=localStorage.getItem('zyb-sa-site-'+ROLE_PAGE)||'';}catch(e){ /* browser storage blocked (private window): the page works without it */ }
  function inSite(site){return !SITE||String(site||'').toLowerCase()===SITE.toLowerCase();}
  function sitesFill(){var el=$('site'),have={};(SV||[]).forEach(function(s){if(s.site)have[s.site]=1;});if(SITE)have[SITE]=1;
    el.innerHTML='<option value="">All sites</option>'+Object.keys(have).sort().map(function(x){return '<option'+(x.toLowerCase()===SITE.toLowerCase()?' selected':'')+'>'+esc(x)+'</option>';}).join('');}
  function setSite(v){SITE=v||'';try{localStorage.setItem('zyb-sa-site-'+ROLE_PAGE,SITE);}catch(e){ /* browser storage blocked (private window): the page works without it */ }if(OV)drawOverview();if(SV&&$('servers').innerHTML)drawServers();}

  document.title=NAME;
  $('app').innerHTML=('<div class="top"><div><div class="eb">Server operations · ' + ZYB_ORG.short + '</div><h1>')+esc(NAME)+'</h1></div><span class="sp"></span><span id="chips"></span><label class="sitef">Site <select id="site" aria-label="Show servers of one site"><option value="">All sites</option></select></label><button type="button" id="refresh">⟳ Refresh</button></div>'
    +'<div class="tabs" role="tablist"><button role="tab" aria-selected="true" data-tab="overview">Overview</button><button role="tab" aria-selected="false" data-tab="ask">Ask the AI</button><button role="tab" aria-selected="false" data-tab="servers">Servers</button><button role="tab" aria-selected="false" data-tab="changes">Change plans</button>'+(EXN?'':'<button role="tab" aria-selected="false" data-tab="uat">UAT checklist</button>')+'</div>'
    +'<section id="tab-overview" role="tabpanel"><p class="note" id="sitenote" hidden></p><div class="k" id="kpis"></div><div class="aig" id="aiband"><div class="card"><h2>Problems by severity<small>AI · ML health checks</small></h2><div class="cv"><canvas id="cv-sev"></canvas></div></div><div class="card"><h2>Server health<small>every server, now</small></h2><div class="cv"><canvas id="cv-srv"></canvas></div></div><div class="card"><h2>What keeps coming up<small>problems by kind</small></h2><div class="cv"><canvas id="cv-kind"></canvas></div></div><div class="card"><h2>Most affected servers<small>open problems</small></h2><div class="cv"><canvas id="cv-top"></canvas></div></div></div><div class="grid g2"><div class="card"><h2>Current problems<small id="fcount"></small></h2><div class="tw" id="findings"><div class="empty">Loading…</div></div></div><div class="card"><h2>Servers<small id="scount"></small></h2><div class="tw" id="sgrid"></div></div></div><div class="card" id="setup" hidden></div><div class="card" id="itsync" hidden></div></section>'
    +'<section id="tab-ask" role="tabpanel" hidden><div class="chat"><div class="card convs"><h2>Conversations</h2><button type="button" id="newconv" class="pri" style="margin-bottom:10px">+ New question</button><div id="convs"></div></div>'
    +'<div class="card"><div id="aistate"></div><div class="log" id="log" aria-live="polite"></div><div class="ask"><textarea id="q" aria-label="Question" placeholder="'+(EXN?'e.g. Why is mail to Gmail stuck in the queue? · Are all DAG copies healthy? · Which Exchange certificates expire soon?':'e.g. Which servers are low on disk? · Why did FS01 restart last night? · Which servers have not been patched for 45 days?')+'"></textarea><button type="button" class="pri" id="send">Ask</button></div><div class="ex" id="ex"></div></div></div></section>'
    +'<section id="tab-servers" role="tabpanel" hidden><div class="card"><h2>'+(EXN?'Exchange servers':'Windows servers')+'<small id="scount2"></small></h2><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px" class="admin-only"><button type="button" class="pri" id="addsrv">+ Add server</button><button type="button" id="logins">Logins</button></div><div class="tw" id="servers"></div>'
    +'<p class="note">Servers in IT Asset Management with a Windows OS and an IP address are added here automatically'+(EXN?'; Exchange servers are recognised from their installed software, a tag "exchange" or their host name (EXCH01, MBX02…) and the reason is shown':'')+'. Removing one here keeps it out.</p></div></section>'
    +'<section id="tab-changes" role="tabpanel" hidden><div class="card"><h2>Change plans<small>proposed by administrators or the AI · approved by an administrator · applied by a person · never executed by the SIEM</small></h2><div class="tw" id="changes"></div></div></section>'
    +(EXN?'':'<section id="tab-uat" role="tabpanel" hidden><div class="card" id="uathead"><div class="empty">Loading…</div></div><div class="card"><h2>Tests<small>a person records each result · the platform only shows the evidence it holds beside it</small></h2><div class="tw" id="uatlist"></div></div><div class="card" id="uatpast" hidden></div></section>');

  $('site').addEventListener('change',function(){setSite(this.value);});
  document.querySelector('.tabs').addEventListener('click',function(e){var b=e.target.closest('[data-tab]');if(b)show(b.getAttribute('data-tab'));});
  function show(t){[].forEach.call(document.querySelectorAll('[data-tab]'),function(b){b.setAttribute('aria-selected',String(b.getAttribute('data-tab')===t));});[].forEach.call(document.querySelectorAll('[role=tabpanel]'),function(p){p.hidden=p.id!=='tab-'+t;});
    if(t==='ask'){aiState();loadConvs();}if(t==='servers')loadServers();if(t==='changes')loadChanges();if(t==='uat')loadUat();try{localStorage.setItem('zyb-sa-tab-'+ROLE_PAGE,t);}catch(e){ /* browser storage blocked (private window): the page works without it */ }}

  /* overview */
  function loadOverview(){return Promise.all([req('GET','/overview'+q),req('GET','/targets'+q)]).then(function(R){OV=R[0];SV=R[1].items||[];drawOverview();loadItSync();}).catch(function(e){$('findings').innerHTML='<div class="err">'+esc(e.message)+'</div>';$('kpis').innerHTML='';});}
  function drawOverview(){var o=OV,b=o.by_severity||{};
    $('chips').innerHTML='<span class="chip '+(o.helper&&o.helper.available?'ok':'bad')+'">WinRM <b>'+(o.helper&&o.helper.available?'ready':'not installed')+'</b></span> <span class="chip '+(o.ai.enabled?'ok':'bad')+'">AI <b>'+(o.ai.enabled?'ready':'off')+'</b></span>'+(o.changes_pending?' <span class="chip"><b>'+o.changes_pending+'</b> change(s) to review</span>':'');
    $('kpis').innerHTML=tile('Servers',o.servers,o.from_itam+' from IT Asset Management')+tile('Checked',o.checked+' / '+o.servers,o.with_login<o.servers?(o.servers-o.with_login)+' without a login':'every '+o.health.interval_min+' min',o.checked<o.servers?'warn':'ok')
      +tile('Critical',b.critical||0,'problems',b.critical?'bad':'ok')+tile('High',b.high||0,'problems',b.high?'warn':'ok')+tile('Medium / low',(b.medium||0)+' / '+(b.low||0),'problems')+tile('Last health check',o.health.last_run?ago(o.health.last_run):'not yet','');
    sitesFill();var SVs=SV.filter(function(s){return inSite(s.site);});
    $('sitenote').hidden=!SITE;$('sitenote').innerHTML=SITE?'Showing site <b>'+esc(SITE)+'</b>: '+SVs.length+' of '+SV.length+' servers in the tables below. The figures above are for every site. <button type="button" class="sm" id="siteall">Show all sites</button>':'';if($('siteall'))$('siteall').onclick=function(){setSite('');};
    var f=(o.findings||[]).map(function(x,i){return [x,i];}).filter(function(p){return inSite(p[0].site);});$('fcount').textContent=f.length?f.length+' open':'';
    var askOk=o.ai&&o.ai.enabled&&can('analyst');$('findings').innerHTML=f.length?'<table><thead><tr><th>Severity</th><th>Problem</th><th>Server</th>'+(askOk?'<th></th>':'')+'</tr></thead><tbody>'+f.map(function(p){var x=p[0];return '<tr data-f="'+p[1]+'" tabindex="0"><td>'+sev(x.severity)+'</td><td>'+esc(x.title)+'</td><td>'+esc(x.server_name)+'</td>'+(askOk?'<td><button type="button" class="sm askai" data-askf="'+p[1]+'">✦ Ask AI</button></td>':'')+'</tr>';}).join('')+'</tbody></table>':'<div class="empty">'+(o.checked?(SITE?'No problems on '+esc(SITE)+' servers.':'No problems found. 👍'):'Nothing checked yet.')+'</div>';
    $('scount').textContent=SVs.length+' servers';
    $('sgrid').innerHTML=SVs.length?'<table><thead><tr><th>Server</th><th>Site</th><th>Status</th><th>Checked</th></tr></thead><tbody>'+SVs.map(function(s){var st=!loginOk(s)?'<span class="pill">no login</span>':!s.last_check?'<span class="pill">not checked</span>':s.worst?sev(s.worst)+' '+s.findings:'<span class="pill ok">ok</span>';return '<tr data-k="'+esc(s.id)+'" tabindex="0"><td><b>'+esc(s.name)+'</b> <span class="muted">'+esc(s.ip)+'</span></td><td>'+esc(s.site)+'</td><td>'+st+'</td><td class="muted">'+ago(s.last_check)+'</td></tr>';}).join('')+'</tbody></table>':'<div class="empty">'+(SITE&&SV.length?'No servers at site '+esc(SITE)+'. Set the site on a server (Servers → Edit).':'No servers yet.')+'</div>';
    var need=[];if(!(o.helper&&o.helper.available))need.push('<li><b>WinRM helper:</b> '+esc((o.helper&&o.helper.reason)||'not installed')+' — the update installs it (<code>netops-cli-setup.sh</code>).</li>');
    if(!SV.length)need.push('<li><b>Servers:</b> none yet — they come from IT Asset Management (see <i>From IT Asset Management</i> below for what was sent and why an asset was not), or add them under Servers.</li>');
    if(SV.length&&!o.with_login)need.push('<li><b>Logins:</b> an administrator sets the '+(EXN?'<code>exchange</code> login (View-Only Organization Management) and the <code>windows</code> login':'<code>windows</code> login')+' under Servers → Logins. Use a dedicated read-only account in <i>Remote Management Users</i>'+(EXN?'':', <i>Event Log Readers</i> and <i>Performance Monitor Users</i>')+' on each server.</li>');
    if(!o.ai.enabled)need.push('<li><b>AI:</b> '+esc(o.ai.reason)+'. Health checks, findings and manual checks work without it.</li>');
    $('setup').hidden=!need.length;$('setup').innerHTML=need.length?'<h2>To finish the setup</h2><ul>'+need.join('')+'</ul>':'';
    drawInsights(f.map(function(p){return p[0];}),SVs);}
  /* AI / ML insight band: every figure from the health checks the page already holds (findings, servers); nothing invented.
     Without the charts library the band is hidden and the tables still carry every figure. */
  var KIND={'cannot-check':'Check could not run'};
  function kindLabel(k){return KIND[k]||String(k||'other').replace(/[-_]+/g,' ').replace(/^./,function(c){return c.toUpperCase();});}
  function drawInsights(F,SVs){var C=window.zybCharts;if(!C||!window.Chart){$('aiband').hidden=true;return;}$('aiband').hidden=false;
    var b={critical:0,high:0,medium:0,low:0};F.forEach(function(x){if(b[x.severity]!=null)b[x.severity]++;});
    if(F.length)C.ring($('cv-sev'),['Critical','High','Medium','Low'],[b.critical,b.high,b.medium,b.low],['crit','warn','acc','mute'],{v:F.length,l:'problems'},{title:'Problems by severity'});
    else C.empty($('cv-sev'),OV&&OV.checked?'No problems found.':'Nothing checked yet.');
    var st={ok:0,prob:0,nc:0,nl:0};SVs.forEach(function(s){if(!loginOk(s))st.nl++;else if(!s.last_check)st.nc++;else if(s.worst)st.prob++;else st.ok++;});
    if(SVs.length)C.ring($('cv-srv'),['Healthy','With problems','Not checked yet','No login'],[st.ok,st.prob,st.nc,st.nl],['ok','crit','acc','mute'],{v:SVs.length,l:'servers'},{title:'Server health'});
    else C.empty($('cv-srv'),'No servers yet.');
    var byK={};F.forEach(function(x){byK[x.kind]=(byK[x.kind]||0)+1;});var K=Object.keys(byK).sort(function(a,c){return byK[c]-byK[a];}).slice(0,8);
    if(K.length)C.bars($('cv-kind'),K.map(kindLabel),[{label:'Problems',data:K.map(function(k){return byK[k];}),color:'purple'}],{horizontal:true,title:'Problems by kind',onClick:function(i){var k=K[i];var q=$('q');if(q&&askable()){show('ask');q.value='Why do we keep seeing "'+kindLabel(k)+'" problems on our '+(EXN?'Exchange':'Windows')+' servers, and what is the lasting fix?';q.focus();}}});
    else C.empty($('cv-kind'),'Nothing to group yet.');
    var R={critical:4,high:3,medium:2,low:1},byS={},worst={};F.forEach(function(x){var n=x.server_name||'?';byS[n]=(byS[n]||0)+1;if(!worst[n]||R[x.severity]>R[worst[n]])worst[n]=x.severity;});
    var T=Object.keys(byS).sort(function(a,c){return byS[c]-byS[a];}).slice(0,8);
    if(T.length)C.bars($('cv-top'),T,[{label:'Open problems',data:T.map(function(n){return byS[n];}),colors:T.map(function(n){return worst[n]==='critical'?'crit':worst[n]==='high'?'warn':'teal';})}],{horizontal:true,title:'Most affected servers'});
    else C.empty($('cv-top'),'No server has an open problem.');
  }
  function askable(){return OV&&OV.ai&&OV.ai.enabled&&can('analyst');}
  // "Ask AI" on a problem: the Ask tab with a question about that problem (the AI investigates with its read-only checks)
  $('findings').addEventListener('click',function(e){var bt=e.target.closest('[data-askf]');if(!bt)return;e.stopPropagation();var x=OV.findings[+bt.getAttribute('data-askf')];if(!x||!askable())return;
    show('ask');$('q').value='Investigate this problem on '+x.server_name+': '+x.title+'. What is the impact, the cause and the safe fix?';$('q').focus();},true);
  /* IT Asset Management → this page: what the sync sent, what is waiting, and why an asset was NOT sent (engine/sysadmin-sync.js in ITAM) */
  function itReq(m,p){return new Promise(function(ok,bad){var x=new XMLHttpRequest();x.open(m,'/api/itam'+p);x.withCredentials=true;x.timeout=120000;if(m!=='GET')x.setRequestHeader('Content-Type','application/json');x.onload=function(){var j=null;try{j=JSON.parse(x.responseText);}catch(e){ /* not JSON: treated as no data */ }if(x.status>=200&&x.status<300&&j)return ok(j);bad(Object.assign(new Error((j&&j.error)||'HTTP '+x.status),{status:x.status}));};x.onerror=x.ontimeout=function(){bad(new Error('IT Asset Management not reachable'));};x.send(m!=='GET'?'{}':null);});}
  function drawItSync(v){var el=$('itsync');el.hidden=false;
    var L=v.last,mine=function(a){return !EXN||a.exchange;};
    var P=(v.pending||[]).filter(mine),K=(v.skipped||[]).filter(mine),S=(v.sent||[]).filter(function(x){return !EXN||(x.roles||[]).indexOf('exchange')>=0;});
    var st=!v.settings.auto?'<span class="pill">automatic sync off</span>':!L?'<span class="pill">first run within 5 minutes of a restart</span>':L.ok?'<span class="pill ok">last run OK '+esc(ago(L.at))+'</span>':'<span class="pill bad">last run failed '+esc(ago(L.at))+'</span>';
    var h='<h2>From IT Asset Management <small>'+S.length+' sent'+(P.length?' · '+P.length+' waiting':'')+(K.length?' · '+K.length+' skipped':'')+'</small>'+(can('admin')?' <button type="button" class="sm" id="itrun" style="float:right">⟳ Sync now</button>':'')+'</h2><p>'+st+'</p>';
    if(L&&!L.ok)h+='<p class="err">'+esc(L.error||'failed')+'</p>';
    if(L&&L.failed&&L.failed.length)h+='<p class="err">Not accepted: '+L.failed.map(function(f){return esc(f.name+' ('+f.error+')');}).join('; ')+'</p>';
    if(P.length)h+='<h3>Waiting to be sent</h3><table><thead><tr><th>Asset</th><th>IP</th><th>Recognised by</th></tr></thead><tbody>'+P.map(function(a){return '<tr><td><b>'+esc(a.name)+'</b></td><td class="mono">'+esc(a.ip)+'</td><td>'+esc(a.exchange||('Windows: '+a.os))+'</td></tr>';}).join('')+'</tbody></table>';
    if(K.length)h+='<h3>Not sent - fix in IT Asset Management</h3><table><thead><tr><th>Asset</th><th>Type</th><th>Why not</th></tr></thead><tbody>'+K.map(function(a){return '<tr><td><b>'+esc(a.name)+'</b>'+(a.exchange?' <span class="muted">'+esc(a.exchange)+'</span>':'')+'</td><td>'+esc(a.type)+'</td><td>'+esc(a.why)+'</td></tr>';}).join('')+'</tbody></table>';
    if(!S.length&&!P.length&&!K.length)h+='<p class="muted">IT Asset Management has no '+(EXN?'asset it recognises as an Exchange server':'Windows server or VM with an IP')+'. '+(EXN?'An Exchange server is recognised by the tag <code>exchange</code>, the installed software "Microsoft Exchange Server", the OS / model / notes naming Exchange, or a host name such as EXCH01, MBX02, EX2019-1 or a Windows server named *MAIL*. Add the tag <code>exchange</code> to the asset, then Sync now.':'Set the asset\'s type to Server or VM, the OS to Windows Server and the management IP.')+'</p>';
    el.innerHTML=h;
    if($('itrun'))$('itrun').onclick=function(){var b=this;b.disabled=true;b.textContent='Syncing…';itReq('POST','/sysadmin-sync/run').then(function(r){toast(r.ok?'Sent '+r.added.length+', updated '+r.upgraded.length+(r.failed.length?', '+r.failed.length+' not accepted':''):'Sync failed: '+r.error,!r.ok);loadOverview();}).catch(function(e){toast(e.message,1);b.disabled=false;b.textContent='⟳ Sync now';});};}
  function loadItSync(){itReq('GET','/sysadmin-sync').then(drawItSync).catch(function(e){var el=$('itsync');el.hidden=false;el.innerHTML='<h2>From IT Asset Management</h2><p class="err">'+esc(e.status===404?'IT Asset Management on the server does not have the server sync yet - run the update (update-all.ps1).':e.status===403?'Operators and administrators can see the sync status.':e.message)+'</p>';});}
  function loginOk(s){return Object.keys(s.logins||{}).some(function(r){return s.logins[r];});}
  $('findings').addEventListener('click',function(e){var r=e.target.closest('tr[data-f]');if(!r)return;var f=OV.findings[+r.getAttribute('data-f')];
    Z.open('Problem · '+f.severity,f.title,Z.kv([['Server',esc(f.server_name)],['Site',esc(f.site||'')],['Kind',esc(f.kind)]])+(f.evidence.length?Z.sec('Evidence','<ul>'+f.evidence.map(function(x){return '<li>'+esc(x)+'</li>';}).join('')+'</ul>'):'')+Z.sec('Recommended fix','<p>'+esc(f.recommendation)+'</p>')+(can('analyst')&&OV.ai.enabled?'<p><button type="button" class="pri" id="askf">Ask the AI about this</button></p>':''));
    if($('askf'))$('askf').onclick=function(){Z.close();show('ask');newConv();$('q').value='Investigate this problem on '+f.server_name+': "'+f.title+'". What is the cause and how do we fix it?';send();};});
  $('sgrid').addEventListener('click',function(e){var r=e.target.closest('tr[data-k]');if(r)detail(r.getAttribute('data-k'));});

  /* AI chat */
  var EX=EXN?['Is mail flowing normally? Check the queues and back pressure','Are all databases mounted and all DAG copies healthy?','Which Exchange certificates expire in the next 60 days?','Is any receive connector an open relay?','When was each mailbox database last backed up?','Are all required Exchange services running?']
    :['Which servers are low on disk space?','Which servers have not been patched for more than 45 days or need a restart?','Why did a server restart unexpectedly in the last 7 days?','Which automatic services are stopped and why?','Which certificates expire in the next 30 days?','Is Active Directory replication healthy?'];
  $('ex').innerHTML=EX.map(function(t){return '<button type="button">'+esc(t)+'</button>';}).join('');
  $('ex').addEventListener('click',function(e){var b=e.target.closest('button');if(b){$('q').value=b.textContent;send();}});
  function md(t){var h=esc(t).replace(/```([\s\S]*?)```/g,function(m,c){return '<pre>'+c.replace(/^\w*\n/,'')+'</pre>';});
    h=h.replace(/^#{1,4} (.+)$/gm,'<h4>$1</h4>').replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
    h=h.replace(/(^|\n)((?:\s*[-•] .+(?:\n|$))+)/g,function(m,p,l){return p+'<ul>'+l.trim().split('\n').map(function(x){return '<li>'+x.replace(/^\s*[-•] /,'')+'</li>';}).join('')+'</ul>';});
    h=h.replace(/(^|\n)((?:\s*\d+[.)] .+(?:\n|$))+)/g,function(m,p,l){return p+'<ol>'+l.trim().split('\n').map(function(x){return '<li>'+x.replace(/^\s*\d+[.)] /,'')+'</li>';}).join('')+'</ol>';});
    h=h.replace(/\n{2,}/g,'<br><br>').replace(/\n/g,'<br>');
    return h.replace(/(<\/h4>|<\/ul>|<\/ol>|<\/pre>)(<br>)+/g,'$1').replace(/(<br>)+(<h4>|<ul>|<ol>|<pre>)/g,'$2');}
  function addMsg(who,html){var d=document.createElement('div');d.className='msg '+who;d.innerHTML='<div class="who">'+(who==='me'?'You':esc(NAME))+'</div><div class="body">'+html+'</div>';$('log').appendChild(d);$('log').scrollTop=$('log').scrollHeight;return d;}
  function aiState(){var a=OV&&OV.ai;if(!a)return;$('aistate').innerHTML=a.enabled?'':'<p class="err">The AI assistant is not available: '+esc(a.reason||'')+'. Health checks, findings and manual checks still work.</p>';$('send').disabled=!a.enabled||!can('analyst');if(!can('analyst'))$('aistate').innerHTML='<p class="muted">Asking the AI needs the analyst role.</p>';}
  function newConv(){CONV=null;$('log').innerHTML='';loadConvs();}
  $('newconv').onclick=newConv;
  function send(){var t=$('q').value.trim();if(!t||$('send').disabled)return;addMsg('me',esc(t));$('q').value='';$('send').disabled=true;
    var w=addMsg('ai','<div class="thinking"><span class="dot"></span>Investigating — reading health results and running checks…</div>');
    req('POST','/ask',{role:ROLE_PAGE,question:t,conversation:CONV}).then(function(r){CONV=r.conversation;w.querySelector('.body').innerHTML=md(r.answer)+(r.steps.length?'<div class="steps">Evidence gathered: '+r.steps.map(function(s){var i=s.input||{};return '<span>'+(s.ok?'✓':'✕')+' '+esc(i.check||s.tool)+(i.server?' ('+esc(i.server)+')':'')+'</span>';}).join('')+'</div>':'');loadConvs();if(r.steps.some(function(s){return s.tool==='propose_change'&&s.ok;}))toast('A change plan was recorded for review (Change plans tab).');})
      .catch(function(e){w.querySelector('.body').innerHTML='<span class="err">'+esc(e.message)+'</span>';}).then(function(){$('send').disabled=!(OV&&OV.ai.enabled);$('q').focus();});}
  $('send').onclick=send;$('q').addEventListener('keydown',function(e){if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();send();}});
  function loadConvs(){if(!can('analyst'))return;req('GET','/conversations'+q).then(function(r){$('convs').innerHTML=(r.items||[]).map(function(c){return '<button type="button" data-c="'+esc(c.id)+'" aria-current="'+(c.id===CONV)+'" title="'+esc(c.title)+'">'+esc(c.title)+'</button>';}).join('')||'<div class="muted">No conversations yet.</div>';}).catch(function(){ /* the conversation list stays as it was; the next open retries */ });}
  $('convs').addEventListener('click',function(e){var b=e.target.closest('[data-c]');if(!b)return;CONV=b.getAttribute('data-c');$('log').innerHTML='';addMsg('ai','<span class="muted">Continuing this conversation — ask a follow-up question.</span>');loadConvs();});

  /* servers */
  function loadServers(){return req('GET','/targets'+q).then(function(r){SV=r.items||[];drawServers();}).catch(function(e){$('servers').innerHTML='<div class="err">'+esc(e.message)+'</div>';});}
  function drawServers(){sitesFill();var SVs=SV.filter(function(s){return inSite(s.site);});$('scount2').textContent=(SITE?SVs.length+' of '+SV.length+' servers · site '+SITE:SV.length+' servers');
    $('servers').innerHTML=SVs.length?'<table><thead><tr><th>Server</th><th>IP</th><th>Site</th><th>Roles</th><th>WinRM</th><th>Login</th><th>Problems</th><th>Checked</th><th>Added by</th></tr></thead><tbody>'+SVs.map(function(s){var lg=(s.roles||[]).map(function(r){return r+': '+(s.logins[r]?esc(s.logins[r].split(': ')[1]||s.logins[r]):'<span class="err">not set</span>');}).join('<br>');
      return '<tr data-k="'+esc(s.id)+'" tabindex="0"><td><b>'+esc(s.name)+'</b></td><td class="mono">'+esc(s.ip)+'</td><td>'+esc(s.site)+'</td><td>'+esc((s.roles||[]).join(', '))+'</td><td class="muted">'+(s.winrm.ssl?'HTTPS '+s.winrm.port+(s.certificate?' · trusted':' · <span class="err">not trusted</span>'):'HTTP '+s.winrm.port+' (encrypted)')+'</td><td class="muted">'+lg+'</td><td>'+(s.worst?sev(s.worst)+' '+s.findings:s.last_check?'<span class="pill ok">none</span>':'–')+'</td><td class="muted">'+ago(s.last_check)+'</td><td class="muted" title="'+esc(s.detected_by||'')+'">'+(s.source==='itam'?'IT Asset Mgmt':'manual')+'</td></tr>';}).join('')+'</tbody></table>':'<div class="empty">'+(SITE&&SV.length?'No servers at site '+esc(SITE)+'.':'No servers yet.')+'</div>';}
  $('servers').addEventListener('click',function(e){var r=e.target.closest('tr[data-k]');if(r)detail(r.getAttribute('data-k'));});
  function catalogue(){return CK?Promise.resolve(CK):req('GET','/checks').then(function(r){CK=r.items||[];return CK;});}
  function fmtData(d){if(d==null)return '<p class="muted">(no data)</p>';if(Array.isArray(d)&&!d.length)return '<p class="muted">none</p>';
    if(Array.isArray(d)&&d.every(function(x){return x&&typeof x==='object'&&!Array.isArray(x);})){var cols=[];d.forEach(function(x){Object.keys(x).forEach(function(k){if(cols.indexOf(k)<0)cols.push(k);});});cols=cols.slice(0,9);
      return '<div class="tw">'+Z.tbl(cols,d.slice(0,100).map(function(x){return cols.map(function(k){var v=x[k];return esc(v==null?'':typeof v==='object'?JSON.stringify(v):String(v));});}))+'</div>';}
    if(typeof d==='object')return Z.kv(Object.keys(d).map(function(k){var v=d[k];return [esc(k),esc(v==null?'':typeof v==='object'?JSON.stringify(v):String(v))];}));
    return '<pre>'+esc(String(d))+'</pre>';}
  function detail(id){Promise.all([req('GET','/targets/'+encodeURIComponent(id)),catalogue()]).then(function(R){var r=R[0],s=r.server,h=r.health,C=R[1].filter(function(c){return (s.roles||[]).indexOf(c.scope)>=0;});
    var res=h&&h.results?Object.keys(h.results).map(function(k){var v=h.results[k],c=C.filter(function(x){return x.id===k;})[0];return Z.sec((c?c.title:k)+' · '+ago(v.at),v.error?'<p class="err">'+esc(v.error)+'</p>':fmtData(v.data));}).join(''):'<p class="muted">Not checked yet'+(loginOk(s)?' — the first health check runs within 15 minutes, or press Check now.':' — set a login first.')+'</p>';
    var html=Z.kv([['IP',esc(s.ip)],['Site',esc(s.site)],['Roles',esc((s.roles||[]).join(', '))],['WinRM',esc(s.winrm.ssl?'HTTPS '+s.winrm.port:'HTTP '+s.winrm.port+' — encrypted by Kerberos / NTLM')+(s.certificate?' · certificate trusted <span class="mono">'+esc(s.certificate.fingerprint.slice(0,23))+'…</span>':'')],['Logins',esc((s.roles||[]).map(function(x){return s.logins[x]?x+' checks: '+s.logins[x].replace(/^[^:]+: /,'')+' (profile '+s.logins[x].split(':')[0]+')':x+' checks: not set';}).join(' · '))],['Added by',esc(s.source==='itam'?'IT Asset Management'+(s.asset_id?' ('+s.asset_id+')':'')+(s.detected_by?' — '+s.detected_by:''):'manual')],['Last health check',s.last_check?ago(s.last_check):'not yet']])
      +(r.findings.length?Z.sec('Problems',Z.tbl(['Severity','Problem','Fix'],r.findings.map(function(f){return [sev(f.severity),esc(f.title)+(f.evidence.length?'<div class="muted">'+esc(f.evidence.join(' · '))+'</div>':''),esc(f.recommendation)];}))):'')
      +'<p style="display:flex;gap:8px;flex-wrap:wrap">'+(can('operator')?'<button type="button" class="pri" id="pollnow">Check now</button><button type="button" id="runck">Run a check</button>':'')+(can('admin')?(s.winrm.ssl?'<button type="button" id="certrd">'+(s.certificate?'Re-check certificate':'Read certificate')+'</button>':'')+'<button type="button" id="edits">Edit</button><button type="button" id="dels" class="danger">Remove</button>':'')+'</p>'
      +'<div id="ckout" class="res"></div><div class="res">'+res+'</div>';
    Z.open('Server',s.name,html);
    if($('pollnow'))$('pollnow').onclick=function(){var b=this;b.disabled=true;b.textContent='Checking…';req('POST','/targets/'+encodeURIComponent(id)+'/poll').then(function(x){toast(x.findings.length?x.findings.length+' problem(s)':'No problems found');detail(id);loadOverview();}).catch(function(e){toast(e.message,1);b.disabled=false;b.textContent='Check now';});};
    if($('runck'))$('runck').onclick=function(){runCheck(s,C);};
    if($('certrd'))$('certrd').onclick=function(){certFlow(s);};
    if($('edits'))$('edits').onclick=function(){serverForm(s);};
    if($('dels'))$('dels').onclick=function(){if(!confirm('Remove '+s.name+'? '+(s.source==='itam'?'IT Asset Management will not add it again.':'')))return;req('DELETE','/targets/'+encodeURIComponent(id)).then(function(){Z.close();toast('Removed');loadServers();loadOverview();}).catch(function(e){toast(e.message,1);});};
  }).catch(function(e){toast(e.message,1);});}
  function runCheck(s,C){var el=$('ckout');
    el.innerHTML='<form class="f" id="ckf"><label class="w">Check<select name="ck">'+C.map(function(c){return '<option value="'+esc(c.id)+'">'+esc(c.title)+(c.personal?' — names people (audited)':'')+(c.admin?' — needs local admin':'')+'</option>';}).join('')+'</select></label><div class="w" id="ckp"></div><div class="w"><button class="pri" type="submit">Run</button> <span class="muted" id="ckst"></span></div></form><div id="ckres"></div>';
    var f=$('ckf');function params(){var c=C.filter(function(x){return x.id===f.ck.value;})[0],p=c.params||{};$('ckp').innerHTML=Object.keys(p).map(function(k){var d=p[k];return '<label>'+esc(k)+(d.type==='enum'?'<select name="p_'+esc(k)+'">'+d.values.map(function(v){return '<option'+(v===d['default']?' selected':'')+'>'+esc(v)+'</option>';}).join('')+'</select>':'<input name="p_'+esc(k)+'" '+(d.type==='int'?'inputmode="numeric" value="'+esc(d['default']||'')+'"':'')+(k==='address'?' placeholder="user@domain"':'')+'>')+'</label>';}).join('');}
    f.ck.onchange=params;params();
    f.onsubmit=function(e){e.preventDefault();var c=C.filter(function(x){return x.id===f.ck.value;})[0],p={};Object.keys(c.params||{}).forEach(function(k){var v=f['p_'+k].value.trim();if(v!=='')p[k]=c.params[k].type==='int'?+v:v;});
      var b=f.querySelector('button[type=submit]');b.disabled=true;$('ckst').textContent='Running on '+s.name+'…';
      req('POST','/targets/'+encodeURIComponent(s.id)+'/check',{check:c.id,params:p}).then(function(r){$('ckst').textContent=(r.ms/1000).toFixed(1)+' s';$('ckres').innerHTML=Z.sec(r.title,fmtData(r.data)+(r.errors.length?'<p class="muted">'+esc(r.errors.join(' · '))+'</p>':''));})
        .catch(function(er){$('ckst').textContent='';$('ckres').innerHTML='<p class="err">'+esc(er.message)+'</p>';}).then(function(){b.disabled=false;});};}
  function certFlow(s){req('POST','/targets/'+encodeURIComponent(s.id)+'/certificate').then(function(r){var same=r.matches===true,changed=r.pinned&&r.matches===false;
    Z.open('WinRM HTTPS certificate',s.name,(changed?'<p class="err"><b>The certificate is DIFFERENT from the trusted one.</b> Only trust it if it was renewed; otherwise someone may be intercepting the connection.</p>':same?'<p><span class="pill ok">matches the trusted certificate</span></p>':'<p class="muted">Nothing was sent to the server except the TLS hello — no user name or password.</p>')
      +Z.kv([['Server',esc(s.name+' · '+s.ip)],['SHA-256 fingerprint','<div class="fp">'+esc(r.fingerprint)+'</div>']])+(same?'':'<p class="muted">Compare it on the server: <code>Get-ChildItem Cert:\\LocalMachine\\My | fl Subject,Thumbprint</code> and the WinRM listener (<code>winrm e winrm/config/listener</code>), then trust it.</p><p><button type="button" class="pri" id="certok">Trust this certificate</button></p>'));
    if($('certok'))$('certok').onclick=function(){req('POST','/targets/'+encodeURIComponent(s.id)+'/certificate/trust',{fingerprint:r.fingerprint}).then(function(){toast('Certificate trusted');detail(s.id);}).catch(function(e){toast(e.message,1);});};}).catch(function(e){toast(e.message,1);});}
  function serverForm(s){s=s||{roles:EXN?['windows','exchange']:['windows'],winrm:{ssl:false,port:5985}};
    Z.open('Server',s.id?'Edit '+s.name:'Add a server','<form class="f" id="sf"><label>Id (letters, digits, dashes)<input name="id" required pattern="[a-z0-9]+(-[a-z0-9]+)*" minlength="2" maxlength="40" value="'+esc(s.id||'')+'"'+(s.id?' readonly':'')+'></label><label>Name<input name="name" value="'+esc(s.name||'')+'"></label><label>IP address or DNS name<input name="ip" required value="'+esc(s.ip||'')+'"></label><label>Site<input name="site" value="'+esc(s.site||'')+'"></label>'
      +'<label class="w"><span><input type="checkbox" name="ex"'+((s.roles||[]).indexOf('exchange')>=0?' checked':'')+'> Exchange server (also gets the Windows checks)</span></label>'
      +'<label><span><input type="checkbox" name="ssl"'+(s.winrm.ssl?' checked':'')+'> WinRM over HTTPS (5986)</span></label><label>WinRM port<input name="port" inputmode="numeric" value="'+esc(s.winrm.port||'')+'"></label>'
      +'<label>Windows login profile<input name="lw" placeholder="windows" value="'+esc((s.login_profiles||{}).windows||'')+'"></label><label>Exchange login profile<input name="le" placeholder="exchange" value="'+esc((s.login_profiles||{}).exchange||'')+'"></label>'
      +'<div class="w"><button class="pri" type="submit">Save</button></div></form>');
    $('sf').onsubmit=function(e){e.preventDefault();var f=e.target,b={id:f.id.value,name:f.name.value,ip:f.ip.value.trim(),site:f.site.value,roles:f.ex.checked?['windows','exchange']:['windows'],winrm:{ssl:f.ssl.checked,port:f.port.value?+f.port.value:undefined},logins:{windows:f.lw.value.trim()||undefined,exchange:f.le.value.trim()||undefined}};
      req('POST','/targets',b).then(function(){toast('Saved');Z.close();loadServers();loadOverview();}).catch(function(er){toast(er.message,1);});};}
  $('addsrv').onclick=function(){serverForm(null);};
  $('logins').onclick=function(){req('GET','/profiles').then(function(r){var P=r.items||{};
    Z.open('Logins · write-only','WinRM accounts','<p class="muted">Use dedicated read-only accounts. Passwords are stored in the SIEM\'s protected secrets file and never shown again. The <b>windows</b> profile is used for Windows checks and the <b>exchange</b> profile for Exchange checks, unless a server names another profile.</p>'
      +Z.tbl(['Profile','User','Auth',''],Object.keys(P).map(function(k){return [esc(k),esc(P[k].user),esc(P[k].auth),'<button type="button" class="danger" data-rm="'+esc(k)+'">Remove</button>'];}))
      +'<form class="f" id="lf" style="margin-top:12px"><label>Profile<input name="id" required value="'+(EXN&&!P.exchange?'exchange':!P.windows?'windows':'')+'" pattern="[a-z0-9]+(-[a-z0-9]+)*"></label><label>Authentication<select name="auth"><option value="negotiate">Negotiate (Kerberos, else NTLM)</option><option value="kerberos">Kerberos</option><option value="ntlm">NTLM</option></select></label><label>User (DOMAIN\\user or user@domain)<input name="u" autocomplete="off" required></label><label>Password<input name="p" type="password" autocomplete="new-password" required></label><div class="w"><button class="pri" type="submit">Save login</button></div></form>'
      +'<p class="note">Least privilege: '+(EXN?'<b>exchange</b> — member of <i>View-Only Organization Management</i> (add the <i>Message Tracking</i> role only if message tracking is wanted) and of <i>Remote Management Users</i> on each Exchange server. ':'')+'<b>windows</b> — a domain account in <i>Remote Management Users</i>, <i>Event Log Readers</i> and <i>Performance Monitor Users</i> on each server (via a GPO restricted group). A few checks (scheduled tasks, roles, shares) need local administrator and say so if refused.</p>');
    $('lf').onsubmit=function(e){e.preventDefault();var f=e.target;req('PUT','/profiles/'+encodeURIComponent(f.id.value.trim()),{username:f.u.value.trim(),password:f.p.value,auth:f.auth.value}).then(function(){toast('Login saved');Z.close();loadServers();loadOverview();}).catch(function(er){toast(er.message,1);});};
    [].forEach.call(document.querySelectorAll('[data-rm]'),function(b){b.onclick=function(){if(!confirm('Remove the login profile '+b.getAttribute('data-rm')+'?'))return;req('PUT','/profiles/'+encodeURIComponent(b.getAttribute('data-rm')),{remove:true}).then(function(){toast('Removed');$('logins').onclick();}).catch(function(er){toast(er.message,1);});};});
  }).catch(function(e){toast(e.message,1);});};

  /* change plans */
  var CH=[];
  function loadChanges(){return req('GET','/changes'+q).then(function(r){CH=r.items||[];var C={proposed:'warn',approved:'ok',rejected:'',applied:'ok',validated:'ok','failed-validation':'bad'};
    $('changes').innerHTML=CH.length?'<table><thead><tr><th>Id</th><th>Server</th><th>Title</th><th>Risk</th><th>Status</th><th>Proposed by</th><th>When</th></tr></thead><tbody>'+CH.map(function(c,i){return '<tr data-c="'+i+'" tabindex="0"><td class="mono">'+esc(c.id)+'</td><td>'+esc(c.device)+'</td><td>'+esc(c.title)+'</td><td>'+esc(c.risk)+'</td><td><span class="pill '+(C[c.status]||'')+'">'+esc(c.status)+'</span></td><td class="muted">'+esc(c.proposed_by)+'</td><td class="muted">'+ago(c.proposed_at)+'</td></tr>';}).join('')+'</tbody></table>':'<div class="empty">No change plans yet. The AI proposes one when a fix needs a change.</div>';}).catch(function(e){$('changes').innerHTML='<div class="err">'+esc(e.message)+'</div>';});}
  $('changes').addEventListener('click',function(e){var r=e.target.closest('tr[data-c]');if(!r)return;var c=CH[+r.getAttribute('data-c')];
    Z.open('Change plan · '+c.status,c.id+' · '+c.title,Z.kv([['Server',esc(c.device)],['Risk',esc(c.risk)],['Proposed by',esc(c.proposed_by)],['Status',esc(c.status)]])+(c.reason?Z.sec('Why','<p>'+esc(c.reason)+'</p>'):'')
      +(c.prechecks.length?Z.sec('Before you start','<pre>'+esc(c.prechecks.join('\n'))+'</pre>'):'')+Z.sec('Steps / PowerShell','<pre>'+esc(c.commands.join('\n'))+'</pre>')+(c.rollback.length?Z.sec('Rollback','<pre>'+esc(c.rollback.join('\n'))+'</pre>'):'')
      +(c.validation?Z.sec('Validation',(c.validation.ok?'<span class="pill ok">passed</span> ':'<span class="pill bad">failed</span> ')+esc(c.validation.summary)):'')
      +'<p style="display:flex;gap:8px;flex-wrap:wrap">'+(c.status==='proposed'&&(can('admin')||(window.zybApproves&&(window.zybApproves('eng:windows')||window.zybApproves('eng:exchange'))))?'<button type="button" class="pri" data-d="approved">Approve</button><button type="button" data-d="rejected">Reject</button>':'')+(c.status==='approved'&&can('operator')?'<button type="button" class="pri" id="applied">I applied it — re-check the server</button>':'')+'</p>');
    [].forEach.call(document.querySelectorAll('[data-d]'),function(b){b.onclick=function(){var cm=prompt('Comment (optional)')||'';req('POST','/changes/'+encodeURIComponent(c.id)+'/decide',{decision:b.getAttribute('data-d'),comment:cm}).then(function(){toast('Recorded');Z.close();loadChanges();}).catch(function(er){toast(er.message,1);});};});
    if($('applied'))$('applied').onclick=function(){var b=this;b.disabled=true;b.textContent='Re-checking…';req('POST','/changes/'+encodeURIComponent(c.id)+'/applied',{note:''}).then(function(x){toast(x.status==='validated'?'Validated: no high or critical problems':'Still problems after the change',x.status!=='validated');Z.close();loadChanges();loadOverview();}).catch(function(er){toast(er.message,1);});};});

  /* UAT checklist (engine/sysadmin/uat.js): a person records each result; four-eyes sign-off by an admin who recorded none */
  var UAT=null,RES={pass:['ok','pass'],fail:['bad','fail'],not_run:['','not run']};
  function loadUat(){if(EXN)return;req('GET','/uat').then(function(v){UAT=v;drawUat();}).catch(function(e){$('uathead').innerHTML='<div class="err">'+esc(e.message)+'</div>';$('uatlist').innerHTML='';});}
  function when(t){return t?new Date(t).toLocaleString():'';}
  function drawUat(){var v=UAT,m=v.summary,so=v.signoff;
    $('uathead').innerHTML='<h2>UAT round '+esc(String(v.round))+' · site '+esc(v.site)+'<small>started '+esc(when(v.started))+(v.started_by?' by '+esc(v.started_by):'')+'</small></h2>'
      +'<div class="k">'+tile('Required passed',m.passed+' / '+m.required,'',m.passed===m.required?'ok':'warn')+tile('Failed',m.failed,'tests',m.failed?'bad':'ok')+tile('Not run',m.not_run,'tests')+tile(v.site+' servers',v.servers.length,v.servers.filter(function(s){return s.last_check;}).length+' checked',v.servers.length?'':'warn')+'</div>'
      +(v.servers.length?'<p class="muted">Servers in this round: '+v.servers.map(function(s){return '<b>'+esc(s.name)+'</b> <span class="mono">'+esc(s.ip)+'</span>';}).join(' · ')+' <button type="button" class="sm" id="uatsite">Show only these servers</button></p>':'<p class="err">No server has the site "'+esc(v.site)+'". Add the UAT servers under Servers with Site = '+esc(v.site)+'.</p>')
      +(so?'<p><span class="pill ok">Signed off</span> by <b>'+esc(so.by)+'</b> '+esc(when(so.at))+(so.note?' — '+esc(so.note):'')+'</p>':'<p class="muted">Sign-off: every required test passed, then an administrator who recorded none of the results signs off.</p>')
      +'<p style="display:flex;gap:8px;flex-wrap:wrap">'+(can('admin')&&!so?'<button type="button" class="pri" id="uatsign"'+(v.ready_to_sign?'':' disabled title="every required test must pass first"')+'>Sign off UAT</button>':'')+(can('admin')?'<button type="button" id="uatnew">Start a new round</button>':'')+'<button type="button" id="uatprint">Print</button></p>';
    $('uatlist').innerHTML='<table><thead><tr><th>Test</th><th>What to do</th><th>Expected</th><th>Platform evidence</th><th>Result</th><th>Recorded</th></tr></thead><tbody>'+v.items.map(function(i){var r=RES[i.result]||RES.not_run;
      return '<tr data-u="'+esc(i.id)+'"'+(can('operator')&&!so?' tabindex="0" class="click"':'')+'><td><b>'+esc(i.title)+'</b>'+(i.required?'':' <span class="muted">(optional)</span>')+'</td><td>'+esc(i.how)+'</td><td>'+esc(i.expect)+'</td><td class="muted">'+(i.evidence?esc(i.evidence):'—')+'</td><td><span class="pill '+r[0]+'">'+esc(r[1])+'</span>'+(i.note?'<div class="muted">'+esc(i.note)+'</div>':'')+'</td><td class="muted">'+(i.by?esc(i.by)+'<br>'+esc(when(i.at))+(i.server?'<br>'+esc(i.server):''):'')+'</td></tr>';}).join('')+'</tbody></table>'
      +(can('operator')&&!so?'<p class="note">Click a test to record its result.</p>':'');
    var P=v.past||[];$('uatpast').hidden=!P.length;$('uatpast').innerHTML=P.length?'<h2>Earlier rounds</h2>'+Z.tbl(['Round','Site','Started','Signed off','Closed'],P.map(function(x){return [esc(String(x.round)),esc(x.site),esc(when(x.started)),x.signoff?esc(x.signoff.by+' · '+when(x.signoff.at)):'<span class="muted">not signed off</span>',esc(when(x.closed)+(x.closed_by?' · '+x.closed_by:''))];})):'';
    if($('uatsite'))$('uatsite').onclick=function(){setSite(v.site);show('servers');};
    if($('uatprint'))$('uatprint').onclick=function(){window.print();};
    if($('uatsign'))$('uatsign').onclick=function(){Z.open('UAT sign-off','Round '+v.round+' · '+v.site,'<form class="f" id="usf"><label class="w">Note<textarea name="note" maxlength="1000" placeholder="e.g. accepted for production roll-out"></textarea></label><div class="w"><button class="pri" type="submit">Sign off</button> <span class="err" data-msg></span></div></form>');
      $('usf').onsubmit=function(e){e.preventDefault();req('POST','/uat/signoff',{note:e.target.note.value.trim()}).then(function(x){UAT=x;Z.close();toast('UAT signed off');drawUat();}).catch(function(er){$('usf').querySelector('[data-msg]').textContent=er.message;});};};
    if($('uatnew'))$('uatnew').onclick=function(){Z.open('New UAT round','The current round is kept under Earlier rounds','<form class="f" id="unf"><label>Site of the test servers<input name="site" maxlength="60" value="'+esc(v.site)+'"></label><label class="w">Why a new round<input name="note" maxlength="500"></label><div class="w"><button class="pri" type="submit">Start</button> <span class="err" data-msg></span></div></form>');
      $('unf').onsubmit=function(e){e.preventDefault();req('POST','/uat/reset',{site:e.target.site.value.trim(),note:e.target.note.value.trim()}).then(function(x){UAT=x;Z.close();toast('Round '+x.round+' started');drawUat();}).catch(function(er){$('unf').querySelector('[data-msg]').textContent=er.message;});};};}
  function uatRecord(id){var i=UAT.items.filter(function(x){return x.id===id;})[0];if(!i||!can('operator')||UAT.signoff)return;
    Z.open('UAT test',i.title,Z.kv([['What to do',esc(i.how)],['Expected',esc(i.expect)],['Platform evidence',i.evidence?esc(i.evidence):'none yet']])
      +'<form class="f" id="urf"><label>Result<select name="result"><option value="pass">Pass</option><option value="fail">Fail</option><option value="not_run">Not run</option></select></label><label>Server<select name="server"><option value="">—</option>'+UAT.servers.map(function(s){return '<option value="'+esc(s.id)+'"'+(s.id===i.server?' selected':'')+'>'+esc(s.name)+'</option>';}).join('')+'</select></label><label class="w">Note (required for a fail: what happened)<textarea name="note" maxlength="1000">'+esc(i.note||'')+'</textarea></label><div class="w"><button class="pri" type="submit">Record</button> <span class="err" data-msg></span></div></form>');
    if(i.result)$('urf').result.value=i.result==='not_run'?'pass':i.result;
    $('urf').onsubmit=function(e){e.preventDefault();var f=e.target;req('POST','/uat/items/'+encodeURIComponent(id),{result:f.result.value,server:f.server.value||undefined,note:f.note.value.trim()||undefined}).then(function(x){UAT=x;Z.close();toast('Recorded');drawUat();}).catch(function(er){f.querySelector('[data-msg]').textContent=er.message;});};}
  if(!EXN){$('uatlist').addEventListener('click',function(e){var r=e.target.closest('tr[data-u]');if(r)uatRecord(r.getAttribute('data-u'));});
    $('uatlist').addEventListener('keydown',function(e){var r=e.target.closest('tr[data-u]');if(r&&e.key==='Enter')uatRecord(r.getAttribute('data-u'));});}

  $('refresh').onclick=function(){loadOverview();var t=document.querySelector('[aria-selected="true"][data-tab]').getAttribute('data-tab');if(t!=='overview')show(t);};
  function start(){[].forEach.call(document.querySelectorAll('.admin-only'),function(x){x.hidden=!can('admin');});
    loadOverview().then(aiState);var t='overview';try{t=localStorage.getItem('zyb-sa-tab-'+ROLE_PAGE)||'overview';}catch(e){ /* browser storage blocked (private window): the page works without it */ }show(t);setInterval(function(){if(!document.hidden)loadOverview();},60000);}
  var xr=new XMLHttpRequest();xr.open('GET','/dashboards/whoami.json');xr.onload=function(){try{var j=JSON.parse(xr.responseText);var rl=String(j.role||'').toLowerCase();if(RANK[rl]!=null)ROLE=rl;}catch(e){ /* not JSON: treated as no data */ }start();};xr.onerror=start;xr.send();
})();
